-- Replace all published Monash adaptations with independently developed recipes.
-- Existing IDs remain stable so likes and weekly-menu references keep working.
begin;

create temporary table recipe_replacements (
  old_title text primary key,
  title text not null,
  summary text not null,
  category text not null,
  servings integer not null,
  preparation_minutes integer not null,
  ingredients text not null,
  instructions text not null,
  phase_note text not null
) on commit drop;

insert into recipe_replacements values
('Aziatische kip-noedelsalade','Koude rijstnoedelsalade met limoen-kip','Frisse salade met rijstnoedels, limoen-kip, komkommer, wortel en sesam.','avondeten',4,35,E'400 g ongemarineerde kipfilet\n240 g rijstnoedels\n160 g komkommer, in linten\n160 g wortel, in lucifers\n120 g rode paprika, in reepjes\n2 el limoensap\n1½ el sojasaus zonder ui of knoflook\n1 el knoflook-geïnfuseerde olie\n2 tl sesamolie\n2 tl geraspte gember\n1 el sesamzaad',E'1. Meng limoensap, sojasaus, sesamolie en gember tot dressing.\n2. Kook de rijstnoedels, spoel koud en laat zorgvuldig uitlekken.\n3. Snijd de kip in dunne repen en bak ze gaar in de geïnfuseerde olie. Laat vijf minuten afkoelen.\n4. Meng noedels, groenten en de helft van de dressing.\n5. Verdeel over vier kommen, leg de kip erop en werk af met de rest van de dressing en sesam.','Controleer sojasaus en rijstnoedels op ui, knoflook en inuline. Verdeel de volledige schaal in vier porties.'),
('Aziatische quinoasalade','Lauwe quinoa-paksoisalade met sinaasappel','Lauwe quinoa met paksoi, wortel, komkommer en een frisse sinaasappel-gemberdressing.','lunch',4,30,E'220 g quinoa\n2 kleine paksoi, grof gesneden\n160 g wortel, in dunne plakjes\n160 g komkommer, in blokjes\n1 sinaasappel\n2 el knoflook-geïnfuseerde olie\n1 el rijstazijn\n2 tl geraspte gember\n20 g pompoenpitten\nPeper en zout',E'1. Spoel en kook de quinoa volgens de verpakking; laat vijf minuten uitdampen.\n2. Bak wortel en paksoi vier minuten in één eetlepel olie zodat ze nog beet hebben.\n3. Rasp wat sinaasappelschil en pers drie eetlepels sap uit. Klop dit met rijstazijn, gember en de resterende olie.\n4. Schep quinoa, warme groenten en komkommer door elkaar.\n5. Verdeel in vier porties en voeg dressing en pompoenpitten toe.','Gebruik alleen het sap en de rasp in de aangegeven hoeveelheid en verdeel de salade in vier porties.'),
('Chocolade-macadamia energiebolletjes','Cacao-haverballetjes met pinda en pompoenpit','Koele snackballetjes van haver, pindakaas, cacao en pompoenpitten.','tussendoor',12,20,E'120 g havermout\n80 g gladde pindakaas van alleen pinda en zout\n45 ml pure ahornsiroop\n25 g pompoenpitten, fijngehakt\n15 g cacaopoeder\n1 el chiazaad\n1 tl vanille-extract\nSnuf zout',E'1. Maal de havermout kort tot grof meel.\n2. Meng met cacao, chia, pompoenpitten en zout.\n3. Roer pindakaas, ahornsiroop en vanille erdoor tot een stevig deeg.\n4. Verdeel het deeg in twaalf stukken en rol met vochtige handen tot balletjes.\n5. Koel minimaal twee uur in een afgesloten doos.','Eén balletje is één portie. Controleer pindakaas en vanille op toegevoegde polyolen, honing of inuline.'),
('Citroenzalm met makrutlimoen','Ovenzalm met dille-mosterdkrieltjes','Ovenzalm met krokante krieltjes, sperziebonen en een frisse dille-mosterdsaus.','avondeten',4,45,E'4 zalmfilets van ca. 150 g\n800 g krielaardappelen, gehalveerd\n280 g sperziebonen\n2 el olijfolie\n1 citroen\n2 tl Dijonmosterd zonder ui of knoflook\n2 el verse dille, fijngehakt\nPeper en zout',E'1. Verwarm de oven voor op 210 °C. Meng de krieltjes met olie, peper en zout en rooster twintig minuten.\n2. Schuif de krieltjes opzij en leg de zalm op de plaat. Rooster nog twaalf tot vijftien minuten.\n3. Kook de sperziebonen in zes minuten beetgaar.\n4. Meng mosterd met twee eetlepels citroensap, dille en twee eetlepels warm water.\n5. Verdeel alles over vier borden en lepel de saus over de zalm.','Gebruik naturel zalm en mosterd zonder ui of knoflook. De saus is verdeeld over vier porties.'),
('Groene kiwi-spinaziesmoothie','Kiwi-komkommer ontbijtbowl','Lepelbare ontbijtbowl met kiwi, komkommer, lactosevrije yoghurt en krokante haver.','ontbijt',2,10,E'2 groene kiwi''s\n200 g lactosevrije yoghurt\n100 g komkommer, in blokjes\n50 g havermout\n20 g walnoten, grof gehakt\n2 tl chiazaad\n1 tl pure ahornsiroop, optioneel',E'1. Rooster de havermout en walnoten drie minuten in een droge pan en laat afkoelen.\n2. Schil de kiwi''s en snijd anderhalve kiwi samen met de komkommer klein.\n3. Verdeel de yoghurt over twee kommen en schep kiwi en komkommer erop.\n4. Voeg de geroosterde haver, walnoten en chia toe.\n5. Garneer met de resterende kiwi en eventueel een kleine hoeveelheid ahornsiroop.','Verdeel alle ingrediënten over twee kommen. Controleer yoghurt op inuline of cichoreiwortel.'),
('Hartige paprika-fetamuffins','Polentamuffins met paprika en bieslook','Hartige, glutenvrije muffins met polenta, paprika, feta en bieslook.','tussendoor',12,35,E'160 g fijne polenta\n80 g rijstmeel\n2 tl bakpoeder\n2 eieren\n220 ml lactosevrije melk\n80 g rode paprika, zeer fijn gesneden\n80 g feta, verkruimeld\n2 el bieslook\n2 el olijfolie\nPeper',E'1. Verwarm de oven voor op 190 °C en vet twaalf muffinvormen licht in.\n2. Meng polenta, rijstmeel, bakpoeder en peper.\n3. Klop eieren, melk en olie apart los.\n4. Spatel nat en droog kort door elkaar en voeg paprika, feta en bieslook toe.\n5. Verdeel over de vormen en bak twintig tot tweeëntwintig minuten. Laat afkoelen op een rooster.','Eén muffin is één portie. Gebruik lactosevrije melk en controleer bakpoeder en feta op ongewenste toevoegingen.'),
('Havermout-banaanpannenkoeken','Haverpannenkoekjes met kiwi en limoen','Kleine haverpannenkoekjes met een frisse topping van kiwi, limoen en lactosevrije yoghurt.','ontbijt',3,25,E'120 g havermout\n60 g rijstmeel\n2 eieren\n220 ml lactosevrije melk\n1 tl bakpoeder\n1 el neutrale olie\n2 groene kiwi''s\n120 g lactosevrije yoghurt\n1 limoen\nSnuf kaneel',E'1. Maal de havermout fijn en meng met rijstmeel, bakpoeder en kaneel.\n2. Klop eieren en melk erdoor en laat het beslag tien minuten rusten.\n3. Bak negen kleine pannenkoekjes in een dun laagje olie.\n4. Meng yoghurt met wat limoenrasp. Snijd de kiwi''s in kleine blokjes.\n5. Serveer per persoon drie pannenkoekjes met yoghurt en kiwi.','Eén portie bestaat uit drie kleine pannenkoekjes met een derde van de topping.'),
('Kruidige wortelfritters','Wortel-polentakoekjes met kruidensaus','Goudbruine wortelkoekjes met polenta en een frisse lactosevrije kruidensaus.','lunch',4,30,E'400 g wortel, grof geraspt\n100 g fijne polenta\n3 eieren\n40 g Parmezaan, geraspt\n2 el bieslook\n1 tl gerookt paprikapoeder\n2 el olijfolie\n160 g lactosevrije yoghurt\n1 el citroensap\n2 el peterselie\nPeper en zout',E'1. Meng yoghurt, citroensap en peterselie en zet de saus koud.\n2. Knijp de geraspte wortel droog in een schone doek.\n3. Meng wortel met polenta, eieren, Parmezaan, bieslook en paprikapoeder. Laat vijf minuten staan.\n4. Vorm twaalf platte koekjes en bak ze in olie aan beide kanten goudbruin.\n5. Serveer drie koekjes per persoon met de kruidensaus.','Drie koekjes en een kwart van de saus vormen één portie. Controleer yoghurt op toegevoegde vezels.'),
('Maple granola met yoghurt','Krokante haverclusters met pecan en kaneel','Ovengebakken haverclusters met pecan, pompoenpit en kaneel.','ontbijt',8,35,E'280 g havermout\n40 g pecannoten, grof gehakt\n40 g pompoenpitten\n2 el chiazaad\n45 ml pure ahornsiroop\n35 ml neutrale olie\n1 tl kaneel\n1 eiwit\nSnuf zout',E'1. Verwarm de oven voor op 165 °C en bekleed een plaat met bakpapier.\n2. Meng haver, noten, pitten, chia, kaneel en zout.\n3. Klop eiwit licht schuimig en roer met olie en ahornsiroop door het havermengsel.\n4. Druk in een dunne, aaneengesloten laag op de bakplaat en bak vijfentwintig minuten zonder te roeren.\n5. Laat volledig afkoelen en breek in clusters. Verdeel in acht porties.','Gebruik één achtste per eetmoment. Serveer eventueel met lactosevrije yoghurt zonder inuline.'),
('Milde kip-madras met rijst','Paprika-gemberkip met tomaat en rijst','Milde stoof van kip, paprika, wortel, tomaat en verse gember.','avondeten',4,40,E'500 g kipdijfilet, in blokjes\n250 g basmatirijst\n300 g tomatenblokjes zonder ui of knoflook\n160 g rode paprika, in blokjes\n160 g wortel, in halve plakjes\n2 el knoflook-geïnfuseerde olie\n2 tl verse gember, geraspt\n1 tl gerookt paprikapoeder\n½ tl gemalen komijn\n100 g babyspinazie\nPeper en zout',E'1. Kook de rijst volgens de verpakking.\n2. Bak de kip rondom bruin in de geïnfuseerde olie.\n3. Voeg wortel, paprika, gember, paprikapoeder en komijn toe en bak drie minuten.\n4. Voeg tomaat toe en laat vijftien minuten zacht stoven.\n5. Laat de spinazie op het einde slinken en serveer met de rijst.','Controleer tomatenblokjes op ui en knoflook. Verdeel stoof en rijst in vier gelijke porties.'),
('Ontbijttortilla’s','Krokante maïstortillacups met ei en spinazie','Ovengebakken tortillacups gevuld met ei, spinazie, tomaat en oude kaas.','ontbijt',4,25,E'4 kleine maïstortilla''s zonder tarwe\n6 eieren\n80 g babyspinazie\n100 g cherrytomaten, in kwarten\n50 g oude kaas, geraspt\n2 el bieslook\n1 tl olijfolie\nPeper en zout',E'1. Verwarm de oven voor op 185 °C en vet vier ruime muffinvormen in.\n2. Verwarm de tortilla''s kort zodat ze buigzaam zijn en druk ze in de vormen.\n3. Laat spinazie kort slinken en verdeel met tomaat over de cups.\n4. Klop eieren met bieslook, peper en zout en schenk in de cups. Bestrooi met kaas.\n5. Bak vijftien tot achttien minuten tot het ei gestold is.','Gebruik maïstortilla''s zonder tarwe, inuline, ui of knoflook. Eén cup is één portie.'),
('Pompoen-wortelsoep','Kabocha-paprikasoep met gember','Fluweelzachte soep van kabocha, geroosterde paprika en gember.','lunch',6,45,E'750 g kabocha-pompoen, in blokjes\n240 g rode paprika, in stukken\n200 g wortel, in plakjes\n1,2 l bouillon zonder ui of knoflook\n2 el knoflook-geïnfuseerde olie\n2 tl verse gember, geraspt\n120 ml lactosevrije kookroom\n1 tl gerookt paprikapoeder\nPeper en zout',E'1. Verwarm de oven voor op 210 °C. Meng pompoen, paprika en wortel met olie en paprikapoeder.\n2. Rooster de groenten vijfentwintig minuten.\n3. Doe de groenten met gember en bouillon in een soeppan en kook tien minuten.\n4. Pureer glad en roer de lactosevrije room erdoor.\n5. Breng op smaak en verdeel in zes kommen.','Gebruik kabocha en bouillon zonder ui of knoflook. Houd één zesde van de pan als portie aan.'),
('Quinoabowl met geroosterde groente en ei','Citroenquinoa met geroosterde wortel en ei','Frisse quinoabowl met geroosterde wortel, spinazie, komkommer en zacht ei.','lunch',2,35,E'140 g quinoa\n240 g wortel, in schuine stukken\n2 eieren\n100 g komkommer, in blokjes\n60 g babyspinazie\n1½ el knoflook-geïnfuseerde olie\n1 citroen\n1 el pompoenpitten\n½ tl gemalen komijn\nPeper en zout',E'1. Verwarm de oven voor op 210 °C. Meng wortel met één eetlepel olie, komijn, peper en zout en rooster vijfentwintig minuten.\n2. Kook de quinoa en laat uitdampen.\n3. Kook de eieren zeven minuten, koel en pel.\n4. Meng quinoa met spinazie, komkommer, citroenrasp, één eetlepel citroensap en de resterende olie.\n5. Verdeel over twee kommen en voeg wortel, ei en pompoenpitten toe.','De ingrediënten zijn over twee volledige kommen verdeeld. Voeg niet zonder portiecontrole extra portiegevoelige groenten toe.'),
('Quinoapap met banaan en yoghurt','Quinoa-ontbijt met kiwi en aardbei','Warm quinoaontbijt met lactosevrije melk, kiwi, aardbei en kaneel.','ontbijt',2,20,E'240 g gekookte quinoa\n250 ml lactosevrije melk\n2 groene kiwi''s\n150 g aardbeien\n20 g walnoten, grof gehakt\n2 tl pure ahornsiroop, optioneel\n½ tl kaneel',E'1. Verwarm quinoa, melk en kaneel tien minuten op laag vuur.\n2. Snijd kiwi en aardbeien vlak voor het serveren.\n3. Verdeel de warme quinoa over twee kommen.\n4. Voeg per kom één kiwi en de helft van de aardbeien toe.\n5. Werk af met walnoten en eventueel een kleine hoeveelheid ahornsiroop.','Verdeel fruit en noten gelijk over twee kommen. Gebruik lactosevrije melk zonder inuline.'),
('Roertofu met wortel en courgette','Krokante tofu-rijstpan met paksoi','Hartige rijstpan met krokante stevige tofu, paksoi, wortel en gember.','lunch',2,30,E'300 g stevige tofu, uitgelekt\n150 g jasmijnrijst\n2 kleine paksoi\n120 g wortel, in dunne reepjes\n1 el knoflook-geïnfuseerde olie\n1 el sojasaus zonder ui of knoflook\n2 tl rijstazijn\n2 tl geraspte gember\n1 tl sesamolie\n1 el sesamzaad',E'1. Kook de rijst en laat vijf minuten uitdampen.\n2. Dep de tofu droog, scheur in grove stukjes en bak krokant in de geïnfuseerde olie.\n3. Voeg wortel, paksoi en gember toe en roerbak vier minuten.\n4. Schep de rijst erdoor en bak nog drie minuten.\n5. Meng sojasaus, rijstazijn en sesamolie erdoor en werk af met sesamzaad.','Gebruik stevige, uitgelekte tofu en controleer sojasaus op ui of knoflook. Verdeel de pan in twee porties.'),
('Romige pasta met gerookte zalm','Citroenpasta met forel en spinazie','Glutenvrije pasta met warmgerookte forel, spinazie, citroen en lactosevrije room.','avondeten',4,30,E'320 g glutenvrije pasta zonder peulvruchtenmeel\n300 g warmgerookte forel, zonder marinade\n200 g babyspinazie\n180 ml lactosevrije kookroom\n1 citroen\n2 el knoflook-geïnfuseerde olie\n2 el verse peterselie\n40 g Parmezaan\nPeper',E'1. Kook de pasta volgens de verpakking en bewaar 150 ml kookwater.\n2. Laat de spinazie slinken in de geïnfuseerde olie.\n3. Voeg room, citroenrasp en twee eetlepels kookwater toe.\n4. Schep pasta en Parmezaan door de saus en verdun indien nodig met kookwater.\n5. Verdeel de forel in grove stukken, schep voorzichtig door de pasta en werk af met peterselie en citroensap.','Kies ongemarineerde forel en lactosevrije room. Verdeel het gerecht in vier porties.'),
('Romige pompoen-saliegnocchi','Krokante aardappelgnocchi met kabocha en citroen','Gebakken aardappelgnocchi met geroosterde kabocha, spinazie, salie en citroen.','avondeten',4,40,E'600 g glutenvrije aardappelgnocchi zonder inuline\n360 g kabocha-pompoen, in kleine blokjes\n160 g babyspinazie\n2 el knoflook-geïnfuseerde olie\n10 salieblaadjes\n1 citroen\n50 g Parmezaan, geraspt\n80 ml lactosevrije kookroom\nPeper en zout',E'1. Verwarm de oven voor op 210 °C. Meng kabocha met één eetlepel olie, peper en zout en rooster twintig minuten.\n2. Kook de gnocchi kort volgens de verpakking en laat zeer goed uitlekken.\n3. Bak de gnocchi in de resterende olie goudbruin; voeg salie de laatste minuut toe.\n4. Voeg spinazie, geroosterde kabocha, room en citroenrasp toe en schep twee minuten om.\n5. Verdeel in vier porties en werk af met Parmezaan en een beetje citroensap.','Controleer gnocchi op tarwe, ui, knoflook en inuline. Gebruik kabocha en verdeel de pan in vier porties.'),
('Snelle chocolade-mugcake','Sinaasappel-cacaocakeje uit de magnetron','Eenpersoons rijstmeelcakeje met cacao en een frisse toets van sinaasappel.','tussendoor',1,7,E'30 g rijstmeel\n12 g cacaopoeder\n18 g tafelsuiker\n¼ tl bakpoeder\n45 ml lactosevrije melk\n12 ml neutrale olie\n½ tl sinaasappelrasp\n1 tl pure chocoladestukjes zonder polyolen\nSnuf zout',E'1. Meng rijstmeel, cacao, suiker, bakpoeder en zout in een ruime mok.\n2. Roer melk, olie en sinaasappelrasp erdoor tot er geen droge plekjes meer zijn.\n3. Strooi de chocoladestukjes erop.\n4. Verwarm zestig seconden op 800 watt en daarna zo nodig per tien seconden.\n5. Laat twee minuten afkoelen voordat je eet.','Dit recept is één portie. Controleer chocolade en bakpoeder op polyolen, inuline en melkbestanddelen.'),
('Snelle zalm-aardappelgratin','Aardappel-zalmschotel met dillekorst','Ovenschotel met dunne aardappel, verse zalm, spinazie en een krokante dillekorst.','avondeten',4,55,E'800 g vastkokende aardappelen, in dunne plakjes\n500 g verse zalm, in blokken\n180 g babyspinazie\n250 ml lactosevrije melk\n2 eieren\n60 g oude kaas, geraspt\n30 g glutenvrij paneermeel zonder ui of knoflook\n2 el dille\n1 el knoflook-geïnfuseerde olie\nPeper en zout',E'1. Verwarm de oven voor op 190 °C en vet een schaal in met de geïnfuseerde olie.\n2. Kook de aardappelplakjes zes minuten voor en laat goed uitlekken.\n3. Verdeel aardappel, spinazie en zalm in lagen over de schaal.\n4. Klop melk en eieren met peper en giet erover. Meng kaas, paneermeel en dille en strooi bovenop.\n5. Bak vijfendertig minuten tot de aardappel gaar en de korst goudbruin is.','Gebruik naturel zalm, lactosevrije melk en paneermeel zonder ui, knoflook of inuline. Verdeel in vier porties.'),
('Spinazie-feta-omelet','Kruiden-eiwrap met spinazie en tomaat','Dunne eiwrap gevuld met spinazie, tomaat, feta en verse kruiden.','lunch',2,20,E'4 eieren\n80 g babyspinazie\n100 g cherrytomaten, in kwarten\n60 g feta\n2 el bieslook\n2 el peterselie\n1 el knoflook-geïnfuseerde olie\nPeper',E'1. Klop de eieren los met bieslook, peterselie en peper.\n2. Bak in de helft van de olie twee dunne omeletten en leg ze op borden.\n3. Bak spinazie en tomaat kort in de resterende olie.\n4. Verdeel de groenten en feta over de omeletten.\n5. Rol stevig op en snijd elke wrap schuin doormidden.','Eén gevulde eiwrap is één portie. Feta is portiegebonden; voeg niet zonder controle extra kaas toe.'),
('Thaise groene kipcurry','Kokos-limoensoep met kip en rijst','Lichte maaltijdsoep met kip, rijst, paksoi, wortel, kokos en limoen.','avondeten',4,40,E'450 g kipfilet, in dunne repen\n180 g jasmijnrijst\n2 kleine paksoi, grof gesneden\n160 g wortel, in linten\n200 ml kokosmelk\n900 ml bouillon zonder ui of knoflook\n2 el knoflook-geïnfuseerde olie\n2 tl verse gember\n1 limoen\n2 el groen van lente-ui\n1 el koriander, optioneel',E'1. Kook de rijst apart en verdeel over vier kommen.\n2. Bak de kip kort in geïnfuseerde olie in een soeppan.\n3. Voeg gember, wortel, bouillon en kokosmelk toe en laat tien minuten zacht koken.\n4. Voeg paksoi toe en kook nog drie minuten. Breng op smaak met limoen.\n5. Schep de soep over de rijst en werk af met groen van lente-ui en eventueel koriander.','Controleer bouillon en kokosmelk op ui, knoflook en inuline. Verdeel kokosmelk en soep over vier porties.'),
('Vegan chocolade-chiapudding','Chocolade-sinaasappel overnight chia','Koude chiapudding met cacao, sinaasappelrasp en aardbei.','ontbijt',4,10,E'40 g chiazaad\n400 ml ongezoete amandeldrink zonder inuline\n20 g cacaopoeder\n30 ml pure ahornsiroop\n1 tl sinaasappelrasp\n1 tl vanille-extract\n160 g aardbeien, in plakjes',E'1. Klop amandeldrink, cacao, ahornsiroop, sinaasappelrasp en vanille glad.\n2. Roer het chiazaad erdoor en laat tien minuten staan.\n3. Roer opnieuw en verdeel over vier afsluitbare potjes.\n4. Zet minimaal zes uur in de koelkast.\n5. Voeg vlak voor het eten per potje een kwart van de aardbeien toe.','Eén potje is één portie. Controleer amandeldrink en vanille op inuline, cichoreiwortel en polyolen.'),
('Worteltaartpap','Warme haver met wortel, sinaasappel en pecan','Romige havermout met zachte wortel, kaneel, sinaasappelrasp en pecannoten.','ontbijt',2,18,E'90 g havermout\n400 ml lactosevrije melk\n100 g wortel, fijn geraspt\n20 g pecannoten, grof gehakt\n2 tl pure ahornsiroop\n½ tl sinaasappelrasp\n½ tl kaneel\nSnuf gemberpoeder',E'1. Doe haver, melk, wortel, kaneel en gember in een pan.\n2. Breng rustig aan de kook en laat acht tot tien minuten zacht garen.\n3. Rooster ondertussen de pecannoten kort in een droge pan.\n4. Roer sinaasappelrasp en ahornsiroop door de pap.\n5. Verdeel over twee kommen en strooi de pecannoten erover.','Verdeel wortel en pecannoten over twee kommen. Gebruik lactosevrije melk zonder toegevoegde vezels.'),
('Zalm met dikke aardappelparten','Plaatmaaltijd met zalm, citroenaardappel en boontjes','Complete ovenplaat met zalm, citroenaardappelen, wortel en sperziebonen.','avondeten',4,50,E'4 zalmfilets van ca. 150 g\n800 g aardappelen, in kleine parten\n240 g wortel, in schuine stukken\n240 g sperziebonen\n2½ el knoflook-geïnfuseerde olie\n1 citroen\n1 tl gedroogde tijm\n1 tl Dijonmosterd zonder ui of knoflook\n2 el peterselie\nPeper en zout',E'1. Verwarm de oven voor op 210 °C. Meng aardappel en wortel met twee eetlepels olie, tijm, peper en zout en rooster vijfentwintig minuten.\n2. Meng de resterende olie met mosterd en citroenrasp en bestrijk de zalm.\n3. Leg zalm en sperziebonen op de plaat en rooster nog twaalf tot vijftien minuten.\n4. Controleer of de zalm gaar is en besprenkel alles met citroensap.\n5. Verdeel over vier borden en werk af met peterselie.','Gebruik naturel zalm en mosterd zonder ui of knoflook. De volledige plaat is bedoeld voor vier porties.'),
('Zalm-ricottafrittata','Mini-eimuffins met zalm en spinazie','Kleine oven-eimuffins met zalm, spinazie, oude kaas en dille.','lunch',6,30,E'8 eieren\n180 g gare naturel zalm, in vlokken\n100 g babyspinazie, fijngehakt\n60 g oude kaas, geraspt\n2 el bieslook\n2 el dille\n1 el olijfolie\nPeper',E'1. Verwarm de oven voor op 185 °C en vet twaalf muffinvormen in.\n2. Laat de spinazie kort slinken en knijp overtollig vocht eruit.\n3. Klop eieren met bieslook, dille en peper.\n4. Verdeel spinazie en zalm over de vormen en schenk het ei erover. Bestrooi met kaas.\n5. Bak zestien tot achttien minuten. Serveer twee muffins per persoon.','Twee muffins vormen één portie. Gebruik ongemarineerde zalm en harde kaas zonder smaaktoevoegingen.'),
('Zalmpokébowl','Sesam-zalmrijstkom met komkommer en wortel','Rijstkom met gebakken zalm, komkommer, wortel, spinazie en sesam-limoendressing.','avondeten',4,35,E'500 g verse zalm, in blokken\n280 g jasmijnrijst\n200 g komkommer, in halve maantjes\n200 g wortel, in linten\n100 g babyspinazie\n1½ el sojasaus zonder ui of knoflook\n1 el limoensap\n2 tl sesamolie\n1 el knoflook-geïnfuseerde olie\n1 el sesamzaad\n2 el groen van lente-ui',E'1. Kook de rijst en laat vijf minuten rusten.\n2. Meng sojasaus, limoensap en sesamolie tot dressing.\n3. Bak de zalm in geïnfuseerde olie rondom goudbruin en net gaar.\n4. Verdeel rijst, komkommer, wortel en spinazie over vier kommen.\n5. Voeg zalm en dressing toe en werk af met sesam en groen van lente-ui.','Gebruik alleen het groene deel van lente-ui en sojasaus zonder ui of knoflook. Verdeel in vier kommen.'),
('Zoete-aardappel-fetafrittata','Kabocha-feta ontbijtgratin','Ovenontbijt met kabocha, ei, spinazie, tomaat en feta.','ontbijt',4,45,E'320 g kabocha-pompoen, in kleine blokjes\n8 eieren\n100 g babyspinazie\n120 g cherrytomaten, gehalveerd\n80 g feta, verkruimeld\n2 el bieslook\n1½ el knoflook-geïnfuseerde olie\n½ tl gerookt paprikapoeder\nPeper en zout',E'1. Verwarm de oven voor op 200 °C. Meng kabocha met één eetlepel olie en paprikapoeder en rooster vijftien minuten.\n2. Vet een ovenschaal in met de resterende olie en verdeel kabocha, spinazie en tomaat erover.\n3. Klop eieren met bieslook, peper en zout en schenk in de schaal.\n4. Verkruimel feta erover en bak twintig tot vijfentwintig minuten.\n5. Laat vijf minuten rusten en snijd in vier gelijke stukken.','Gebruik kabocha; andere pompoensoorten zijn niet één-op-één uitwisselbaar. Eén kwart van de schaal is één portie.');

update public.curated_recipes as recipe
set title = replacement.title,
    summary = replacement.summary,
    category = replacement.category,
    source_name = 'Fodmap-Tracker',
    source_url = 'https://fodmaptracker20.vercel.app',
    suitable_for_elimination = true,
    servings = replacement.servings,
    preparation_minutes = replacement.preparation_minutes,
    ingredients = replacement.ingredients,
    instructions = replacement.instructions,
    attribution_note = 'Origineel recept, onafhankelijk ontwikkeld en geschreven door Fodmap-Tracker.',
    phase_note = replacement.phase_note,
    published = true
from recipe_replacements as replacement
where recipe.title = replacement.old_title
  and recipe.source_name = 'Monash FODMAP';

do $$
declare
  remaining integer;
begin
  select count(*) into remaining
  from public.curated_recipes
  where source_name = 'Monash FODMAP' and published = true;

  if remaining <> 0 then
    raise exception 'Replacement incomplete: % published Monash recipes remain', remaining;
  end if;
end $$;

commit;
